import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Eye, EyeOff, Mail, Lock } from 'lucide-react';
import '../styles/SignInPage.css';

export default function SignInPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [fullName, setFullName] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', { email, password, fullName });
    // TODO: Add authentication logic here
  };

  return (
    <div className="signin-page">
      {/* Back to home */}
      <Link to="/" className="signin-back-link">
        ← Back to home
      </Link>

      {/* Container */}
      <div className="signin-container">
        <div className="signin-card">
          {/* Title */}
          <h1 className="signin-main-title">
            {isSignUp ? 'Create your account' : 'Log in to continue your learning journey'}
          </h1>

          {/* Subtitle */}
          <p className="signin-subtitle">
            {isSignUp
              ? 'Join us and start learning from the best institutions.'
              : 'Welcome back! Please enter your details to access your account.'}
          </p>

          <form onSubmit={handleSubmit} className="signin-form">
            {isSignUp && (
              <div className="form-group">
                <div className="input-with-icon">
                  <Mail size={20} className="input-icon" />
                  <input
                    type="text"
                    placeholder="Full name"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    required={isSignUp}
                  />
                </div>
              </div>
            )}

            {/* Email Input */}
            <div className="form-group">
              <div className="input-with-icon">
                <Mail size={20} className="input-icon" />
                <input
                  type="email"
                  placeholder="Email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
            </div>

            {/* Password Input */}
            <div className="form-group">
              <div className="input-with-icon">
                <Lock size={20} className="input-icon" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  placeholder="Password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
                <button
                  type="button"
                  className="toggle-password-btn"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
            </div>

            {isSignUp && (
              <div className="form-group">
                <div className="input-with-icon">
                  <Lock size={20} className="input-icon" />
                  <input
                    type={showConfirmPassword ? 'text' : 'password'}
                    placeholder="Confirm password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    required={isSignUp}
                  />
                  <button
                    type="button"
                    className="toggle-password-btn"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  >
                    {showConfirmPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                  </button>
                </div>
              </div>
            )}

            {!isSignUp && (
              <div className="forgot-password-section">
                <a href="#" className="forgot-password-link">
                  Forgot password?
                </a>
              </div>
            )}

            {/* Continue Button */}
            <button type="submit" className="continue-btn">
              {isSignUp ? 'Create Account' : 'Continue'}
            </button>
          </form>

          {/* Divider */}
          <div className="divider">
            <span>Or</span>
          </div>

          {/* Sign up / Log in link */}
          <div className="signup-section">
            <p className="signup-text">
              {isSignUp ? (
                <>
                  Already have an account?{' '}
                  <button
                    type="button"
                    className="signup-link"
                    onClick={() => {
                      setIsSignUp(false);
                      setFullName('');
                      setConfirmPassword('');
                    }}
                  >
                    Log in
                  </button>
                </>
              ) : (
                <>
                  Don't have an account?{' '}
                  <button
                    type="button"
                    className="signup-link"
                    onClick={() => {
                      setIsSignUp(true);
                      setPassword('');
                      setEmail('');
                    }}
                  >
                    Sign up
                  </button>
                </>
              )}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
